html:
{#- Interview Report, laid out like Luuka's interview report: the day's panel, the
    candidates with their qualifications, experience and the panel's verdict, the
    recommendations, and the signatures of the Human Resource Manager, the Executive
    Director and the Head of Department. -#}
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- macro lines(value) -%}{{ v(value) | replace("\n", "<br>") }}{%- endmacro -%}
{%- macro signer(user, role, on) -%}
	<p style="margin: 34px 0 0">..................................................</p>
	<p style="margin: 2px 0 0">{{ v(frappe.db.get_value("User", user, "full_name") if user else "") }}
		({{ v(role) }}){% if on %}<br><small>{{ frappe.utils.format_date(on) }}</small>{% endif %}</p>
{%- endmacro -%}
{%- set logo = frappe.db.get_single_value("HRMS Addon Branding", "company_logo") -%}
{%- set position = doc.designation or frappe.db.get_value("Job Opening", doc.job_opening, "job_title") or doc.job_opening -%}
{%- set day = frappe.utils.getdate(doc.interview_date) if doc.interview_date else none -%}
{%- set suffix = ("th" if 10 < day.day % 100 < 14 else {1: "st", 2: "nd", 3: "rd"}.get(day.day % 10, "th")) if day else "" -%}
{%- set hod_role = (frappe.db.get_value("Employee", {"user_id": doc.head_of_department}, "designation")
    if doc.head_of_department else "") or "Head of Department" -%}
<style>
	.lpl-report { font-family: Arial, Helvetica, sans-serif; font-size: 10.5px; color: #000; }
	.lpl-report p { margin: 0 0 4px; }
	.lpl-report h3 { font-size: 12.5px; font-weight: bold; margin: 6px 0 10px; }
	.lpl-report table.grid { width: 100%; border-collapse: collapse; margin: 6px 0 10px; }
	.lpl-report .grid tr { page-break-inside: avoid; }
	.lpl-report .grid th, .lpl-report .grid td { border: 1px solid #555; padding: 4px 6px; vertical-align: top; text-align: left; }
	.lpl-report .grid th { font-weight: bold; background: #f2f2f2; }
	.lpl-report .no { width: 4%; text-align: center; }
	.lpl-report .panel { margin: 2px 0 8px 18px; padding: 0; }
	.lpl-report .verdict { color: #333; }
	.lpl-report .signatures td { width: 50%; vertical-align: top; padding-right: 24px; }
</style>
<div class="lpl-report">
	{%- if logo %}<p><img src="{{ logo }}" style="max-height: 48px"></p>{% endif %}
	<h3>INTERVIEW REPORT FOR {{ v(position) | upper }}{% if day %} {{ day.day }}{{ suffix | upper }}
		{{ frappe.utils.formatdate(doc.interview_date, "MMMM yyyy") | upper }}{% endif %}</h3>
	<p><b>Position:</b> {{ v(position) | upper }}</p>
	<p><b>Forwarded to:</b> {{ v(doc.forwarded_to) }}</p>
	<p><b>Thru:</b> {{ v(doc.through) }}</p>
	<p><b>Prepared by:</b> {{ v(doc.prepared_by_name) }}{% if doc.prepared_by_designation %} ({{ v(doc.prepared_by_designation) }}){% endif %}</p>
	<p style="margin-top: 8px">The candidates were interviewed on
		{{ frappe.utils.format_date(doc.interview_date) if doc.interview_date else "" }} by a panel consisting of:-</p>
	<ol class="panel">
		{%- for member in doc.panel %}
		<li>{{ v(member.interviewer_name or member.interviewer) }}{% if member.designation %} ({{ v(member.designation) }}){% endif %}</li>
		{%- endfor %}
	</ol>
	<p>Below are the details of interviewed candidates and panel recommendations;</p>
	<table class="grid">
		<tr>
			<th class="no">No.</th>
			<th style="width: 20%">Name</th>
			<th style="width: 25%">Qualification</th>
			<th style="width: 25%">Experience</th>
			<th>Remarks</th>
		</tr>
		{%- for row in doc.candidates %}
		<tr>
			<td class="no">{{ loop.index }}</td>
			<td>{{ v([row.applicant_name, row.phone_number, row.email_id] | select | join(", ")) }}</td>
			<td>{{ lines(row.qualification) }}</td>
			<td>{{ lines(row.experience) }}</td>
			<td>{{ lines(row.remarks) }}
				{%- if row.average_score or row.panel_recommendations %}
				<br><small class="verdict">
					{%- if row.average_score %}Panel score {{ frappe.utils.flt(row.average_score, 2) }}%{% if row.score_band %} ({{ v(row.score_band) }}){% endif %}{% endif -%}
					{%- if row.panel_recommendations %}{% if row.average_score %}; {% endif %}{{ v(row.panel_recommendations) }}{% endif -%}
					{%- if row.decision %}; decision: {{ v(row.decision) }}{% endif -%}
				</small>
				{%- endif %}</td>
		</tr>
		{%- endfor %}
	</table>
	<p><b>Recommendations</b></p>
	<p>{{ lines(doc.recommendations) }}</p>
	<table class="signatures" style="width: 100%; margin-top: 10px">
		<tr>
			<td>{{ signer(doc.hrm_approver, "Human Resource Manager", doc.hrm_approved_on) }}</td>
			<td>{{ signer(doc.ed_approver, "Executive Director", doc.ed_approved_on) }}</td>
		</tr>
		<tr>
			<td>{{ signer(doc.head_of_department, hod_role, none) }}</td>
			<td></td>
		</tr>
	</table>
</div>
